import React, { useEffect, useRef } from 'react';
import { View, StyleSheet, Platform } from 'react-native';

const vertexShaderGLSL = `
attribute vec2 position;
varying vec2 vUv;
void main() {
  vUv = position * 0.5 + 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const fragmentShaderGLSL = `
precision highp float;
varying vec2 vUv;

uniform vec2  u_resolution;
uniform float u_time;
uniform float u_grain;
uniform vec3  u_colors[4];
uniform vec3  u_bg;

vec3 permute(vec3 x) { return mod(((x*34.0)+1.0)*x, 289.0); }

float snoise(vec2 v){
  const vec4 C = vec4(0.211324865405187, 0.366025403784439,
           -0.577350269189626, 0.024390243902439);
  vec2 i  = floor(v + dot(v, C.yy) );
  vec2 x0 = v -   i + dot(i, C.xx);
  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
  + i.x + vec3(0.0, i1.x, 1.0 ));
  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy),
    dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

void main() {
  vec2 uv = vUv;
  float ratio = u_resolution.x / u_resolution.y;
  vec2 p = uv - 0.5;
  p.x *= ratio;

  float t = u_time * 0.55;

  float n1 = snoise(p * 0.65 + vec2(t * 0.45, -t * 0.55));
  float n2 = snoise(p * 0.85 + vec2(-t * 0.35, t * 0.45) + n1 * 0.35);
  float n3 = snoise(p * 1.15 + vec2(t * 0.25, -t * 0.35) + n2 * 0.3);

  vec3 col = u_bg;
  
  float dist = length(p) * 1.5;
  float vignette = 1.0 - smoothstep(0.3, 1.2, dist);
  
  col = mix(col, u_colors[0], smoothstep(-0.2, 0.5, n1) * 0.9);
  col = mix(col, u_colors[1], smoothstep(-0.1, 0.6, n2) * 0.8);
  col = mix(col, u_colors[2], smoothstep(-0.3, 0.4, n3) * 0.7);
  col = mix(col, u_colors[3], smoothstep(0.0, 0.7, n1 * n2) * 0.6);

  float glow = smoothstep(0.8, 0.0, dist) * 0.45;
  col += u_colors[1] * glow;

  col = mix(col * 0.2, col, vignette);

  float grain = fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453 + u_time);
  col += (grain - 0.5) * u_grain * 0.12;

  gl_FragColor = vec4(col, 1.0);
}
`;

export interface VelarisShaderProps {
  bg?: string;
  colors?: string[];
  speed?: number;
  grain?: number;
  height?: string | number;
  style?: any;
  className?: string;
  children?: React.ReactNode;
}

export type VelarisProps = VelarisShaderProps;

const DEFAULT_COLORS = ['#86efac', '#4ade80', '#059669', '#000000'];

export const VelarisShader: React.FC<VelarisShaderProps> = ({
  bg = '#000000',
  colors = DEFAULT_COLORS,
  speed = 2.0,
  grain = 0.3,
  height,
  style,
  children,
}) => {
  const canvasRef = useRef<any>(null);
  const containerRef = useRef<any>(null);

  const hexToRgb = (hex: string): [number, number, number] => {
    const h = hex.replace('#', '');
    return [
      parseInt(h.slice(0, 2), 16) / 255,
      parseInt(h.slice(2, 4), 16) / 255,
      parseInt(h.slice(4, 6), 16) / 255,
    ];
  };

  useEffect(() => {
    if (Platform.OS !== 'web' || process.env.NODE_ENV === 'test') return;

    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const gl =
      canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    if (!gl) return;

    const createShader = (type: number, src: string) => {
      const s = gl.createShader(type)!;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      return s;
    };

    const vertShader = createShader(gl.VERTEX_SHADER, vertexShaderGLSL);
    const fragShader = createShader(gl.FRAGMENT_SHADER, fragmentShaderGLSL);

    const program = gl.createProgram()!;
    gl.attachShader(program, vertShader);
    gl.attachShader(program, fragShader);
    gl.linkProgram(program);
    gl.useProgram(program);

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
      gl.STATIC_DRAW
    );

    const pos = gl.getAttribLocation(program, 'position');
    gl.enableVertexAttribArray(pos);
    gl.vertexAttribPointer(pos, 2, gl.FLOAT, false, 0, 0);

    const locs = {
      res: gl.getUniformLocation(program, 'u_resolution'),
      time: gl.getUniformLocation(program, 'u_time'),
      grain: gl.getUniformLocation(program, 'u_grain'),
      colors: gl.getUniformLocation(program, 'u_colors'),
      bg: gl.getUniformLocation(program, 'u_bg'),
    };

    const resize = () => {
      if (!container || !canvas) return;
      const parent = container.parentElement || container;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width =
        (container.clientWidth || container.offsetWidth || parent.clientWidth || (typeof window !== 'undefined' ? window.innerWidth : 300)) * dpr;
      const heightVal =
        (container.clientHeight || container.offsetHeight || parent.clientHeight || 180) * dpr;
      if (width > 0 && heightVal > 0) {
        canvas.width = width;
        canvas.height = heightVal;
        gl.viewport(0, 0, width, heightVal);
      }
    };

    resize();
    const timeoutId = setTimeout(resize, 100);

    let ro: any;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(resize);
      ro.observe(container);
      if (container.parentElement) {
        ro.observe(container.parentElement);
      }
    }

    if (typeof window !== 'undefined') {
      window.addEventListener('resize', resize);
    }

    let raf: number;
    const render = (t: number) => {
      gl.uniform2f(locs.res, canvas.width, canvas.height);
      gl.uniform1f(locs.time, t * 0.001 * speed);
      gl.uniform1f(locs.grain, grain);
      gl.uniform3f(locs.bg, ...hexToRgb(bg));

      const flat = new Float32Array(colors.slice(0, 4).flatMap(hexToRgb));
      gl.uniform3fv(locs.colors, flat);

      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      raf = requestAnimationFrame(render);
    };

    raf = requestAnimationFrame(render);

    return () => {
      clearTimeout(timeoutId);
      if (typeof window !== 'undefined') {
        window.removeEventListener('resize', resize);
      }
      if (ro) ro.disconnect();
      if (raf) cancelAnimationFrame(raf);
      try {
        gl.deleteProgram(program);
        gl.deleteShader(vertShader);
        gl.deleteShader(fragShader);
        gl.deleteBuffer(buffer);
      } catch (e) {}
    };
  }, [bg, colors, speed, grain]);

  const containerStyle = [
    styles.webContainer,
    height ? { height } : null,
    style,
  ];

  if (Platform.OS !== 'web') {
    return (
      <View style={[styles.fallbackContainer, height ? { height } : null, style]}>
        {children}
      </View>
    );
  }

  return (
    <View ref={containerRef} style={containerStyle}>
      {/* @ts-ignore */}
      <canvas
        ref={canvasRef}
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
          opacity: 1.0,
        }}
      />
      <View style={styles.childrenWrapper}>{children}</View>
    </View>
  );
};

const styles = StyleSheet.create({
  webContainer: {
    position: 'relative',
    width: '100%',
    overflow: 'hidden',
  },
  fallbackContainer: {
    position: 'relative',
    width: '100%',
    overflow: 'hidden',
  },
  childrenWrapper: {
    position: 'relative',
    zIndex: 10,
    width: '100%',
  },
});

export const Velaris = VelarisShader;
export default VelarisShader;

